 * Unit tests for org.apache.commons.math.util.MathUtils.equals(double, double)
 */
public class MathUtils_equals_TriageGen0Test {





    @Test
    public void testEquals_NaN() {
        // The implementation explicitly handles NaN: (Double.isNaN(x) && Double.isNaN(y))
        assertTrue("NaN should equal NaN according to this method", MathUtils.equals(Double.NaN, Double.NaN));

        // Test NaN mixed with real numbers
        assertFalse("NaN should not equal 1.0", MathUtils.equals(Double.NaN, 1.0));
        assertFalse("1.0 should not equal NaN", MathUtils.equals(1.0, Double.NaN));
    }


